package com.happybananas.tracezilla;
import com.fasterxml.jackson.databind.*;import com.happybananas.tracezilla.shopify.*;import com.happybananas.tracezilla.tracezilla.*;import com.happybananas.tracezilla.workflow.*;import java.util.*;
public final class Main {private Main(){}public static void main(String[] args){try{var json=Arrays.asList(args).contains("--json");var limit=Arrays.stream(args).filter(v->v.startsWith("--limit=")).findFirst().map(v->Integer.parseInt(v.substring(8))).orElse(10);var config=Configuration.fromEnvironment();var result=new CompareCatalogs(new ShopifyCatalog(new ShopifyClient(config)),new TracezillaCatalog(config)).run(limit);if(json){System.out.println(new ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(Map.of("status",result.status(),"display_limit",result.displayLimit(),"matched_count",result.presentInBoth().size(),"only_in_shopify_count",result.onlyInShopify().size(),"only_in_tracezilla_count",result.onlyInTracezilla().size(),"present_in_both",result.presentInBoth(),"only_in_shopify",result.onlyInShopify(),"only_in_tracezilla",result.onlyInTracezilla())));}else render(result);}catch(Exception error){System.err.println("Comparison failed: "+error.getMessage());System.exit(1);}}
private static void render(CompareCatalogs.Result r){System.out.printf("%-24s %-10s %-12s %s%n","SKU","Shopify","tracezilla","Result");System.out.println("-".repeat(72));var rows=new ArrayList<String[]>();r.presentInBoth().stream().limit(r.displayLimit()).forEach(s->rows.add(new String[]{s,"Yes","Yes","Match"}));r.onlyInShopify().stream().limit(r.displayLimit()).forEach(s->rows.add(new String[]{s,"Yes","No","Missing in tracezilla"}));r.onlyInTracezilla().stream().limit(r.displayLimit()).forEach(s->rows.add(new String[]{s,"No","Yes","Missing in Shopify"}));rows.stream().sorted(Comparator.comparing(a->a[0])).forEach(a->System.out.printf("%-24s %-10s %-12s %s%n",(Object[])a));System.out.printf("%nMatched: %d; missing in tracezilla: %d; missing in Shopify: %d%nShowing at most %d rows from each result category.%n",r.presentInBoth().size(),r.onlyInShopify().size(),r.onlyInTracezilla().size(),r.displayLimit());}}
